{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "In rats, bupropion rapidly equilibrated across the BBB with a steady-state Kp,uu of 1.9 by quantitative microdialysis, demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Hydroxybupropion, a close analog, also showed rapid BBB equilibration with a Kp,uu of 1.7 in rat microdialysis, supporting CNS access in this structural neighborhood.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "The ketoprofen-lysine amide prodrug crossed the rat BBB via LAT1-mediated uptake in situ brain perfusion, with rapid brain uptake from blood, supporting CNS access for ketoprofen-like scaffolds.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest retrieved analogs with direct systemic CNS-exposure evidence are predominantly positive: bupropion and hydroxybupropion show Kp,uu >1.5, ketoprofen prodrugs show LAT1-mediated brain uptake, and ketoprofen/dexketoprofen are detected in human CSF. Negative uptake records come from more distant analogs and are outweighed by the condition-matched positive evidence.",
  "evidence_gaps": [
    "No direct query-specific brain or CSF measurement is available; evidence relies on analogs with Morgan similarity 0.30-0.44.",
    "Some ketoprofen total CSF/plasma ratios are very low (<0.006), although unbound CSF levels equilibrate with free plasma; unbound Kp,uu for the query is not directly available.",
    "Negative brain uptake records for MBDA and CL 316,243 are from structurally more distant molecules and may not transfer to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

